const source = fs.readFileSync(filename, 'utf8').split('// --- readiness(): all prerequisites present ---')[0];
const context = {require: createRequire(filename), console};
vm.runInNewContext(source + `
const input = inspectionOnlyBaseline({prAuthor:'outsider', isCrossRepository:true});
input.ciDefinitionsChanged = true;
const result = readiness(input);
console.log(JSON.stringify({ready:result.ready, fallback:input.fallback, items:result.items}, null, 2));
`, context);
